actions.script:
File upload = new File(job.fileLocation as String)
long size = upload.exists() ? upload.length() : 0L
if (offset != size) {
    ec.message.addError("Chunk at ${offset} does not follow the ${size} bytes received, start the upload again")
    return
}
// append the chunk: the file grows on disk, never in memory
InputStream chunk = file instanceof byte[] ? new ByteArrayInputStream((byte[]) file) : file.getInputStream()
chunk.withCloseable { InputStream is -> new FileOutputStream(upload, true).withCloseable { is.transferTo(it) } }
Map fields = [ownerDataTransferId: ownerDataTransferId, fileSize: upload.length(),
              progress: "Received ${upload.length()} bytes".toString()]
if (last) {
    boolean valid = false
    try {
        new java.util.zip.ZipFile(upload).withCloseable { zip ->
            def OwnerDataTransfer = ec.resource.script('component://growerp/service/OwnerDataTransfer.groovy', null)
            valid = OwnerDataTransfer.manifest(zip)?.ownerPartyId as boolean
        }
    } catch (Exception e) {
        valid = false
    }
    if (valid) {
        fields.status = 'QUEUED'
    } else {
        upload.delete()
        fields.putAll([status: 'FAILED', fileLocation: null, completedDate: ec.user.nowTimestamp,
                errorMessage: "${fileName} is not a GrowERP company data file".toString()])
    }
}
// committed before the worker starts, it runs on another thread
ec.service.sync().name('update#growerp.general.OwnerDataTransfer').parameters(fields)
    .requireNewTransaction(true).call()
if (fields.status == 'QUEUED')
    ec.service.async().name('growerp.100.OwnerDataServices100.run#OwnerDataTransfer')
        .parameters([ownerDataTransferId: ownerDataTransferId]).call()

import groovy.json.JsonOutput
import java.util.zip.ZipFile

ec.artifactExecution.disableAuthz()
def job = ec.entity.find('growerp.general.OwnerDataTransfer')
        .condition('ownerDataTransferId', ownerDataTransferId).useCache(false).one()
if (job == null) return
// the async worker has no user: run as the one who asked
if (job.username) ec.user.internalLoginUser(job.username)
Closure update = { Map fields ->
    ec.service.sync().name('update#growerp.general.OwnerDataTransfer')
        .parameters(fields + [ownerDataTransferId: ownerDataTransferId])
        .requireNewTransaction(true).disableAuthz().call()
}
Closure progress = { String message -> update([progress: message]) }
update([status: 'RUNNING', progress: 'Started'])
File file = new File(job.fileLocation as String)
// a big company takes long: hours, not the default minutes
int timeout = 12 * 3600
try {
    def OwnerDataTransfer = ec.resource.script('component://growerp/service/OwnerDataTransfer.groovy', null)
    def transfer = OwnerDataTransfer.newInstance(ec, progress)
    if (job.direction == 'EXPORT') {
        Map result = ec.transaction.runUseOrBegin(timeout, 'Owner data download failed') {
            transfer.export(job.ownerPartyId, file)
        }
        String day = ec.user.nowTimestamp.toLocalDateTime().toLocalDate().toString()
        update([status: 'DONE', progress: "${result.counts.values().sum() ?: 0} records, ${result.files} files".toString(),
                fileName: "growerp-data-${job.ownerPartyId}-${day}.zip".toString(), fileSize: file.length(),
                downloadToken: UUID.randomUUID().toString(),
                countsJson: JsonOutput.toJson(result.counts), completedDate: ec.user.nowTimestamp])
    } else {
        Map result
        new ZipFile(file).withCloseable { ZipFile zip ->
            List conflicts = transfer.conflicts(zip)
            if (conflicts) throw new IllegalStateException('Not loaded: ' + conflicts.join(', '))
            result = ec.transaction.runUseOrBegin(timeout, 'Owner data upload failed') {
                transfer.load(zip, new File(file.parentFile, "${ownerDataTransferId}-load"))
            }
        }
        file.delete()
        update([status: 'DONE', newOwnerPartyId: result.ownerPartyId, fileLocation: null,
                progress: "${result.counts.values().sum() ?: 0} records, ${result.files} files, ${result.skipped.size()} skipped".toString(),
                countsJson: JsonOutput.toJson(result.counts), completedDate: ec.user.nowTimestamp])
    }
} catch (Throwable t) {
    ec.logger.error("Owner data ${job.direction} ${ownerDataTransferId} failed", t)
    ec.message.clearErrors()
    file.delete()
    update([status: 'FAILED', errorMessage: (t.message ?: t.toString()).take(4000),
            fileLocation: null, completedDate: ec.user.nowTimestamp])
}
